import{_ as e,c as l,o as n,a3 as a}from"./chunks/framework.BusRvirq.js";const f=JSON.parse('{"title":"데이터 이관 완료 및 정합성 검증 확인서 (Data Migration Sign-off)","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/public/templates/08_Data_Migration_Signoff_template.html"}]]},"headers":[],"relativePath":"public/templates/08_Data_Migration_Signoff_template.md","filePath":"public/templates/08_Data_Migration_Signoff_template.md","lastUpdated":1790810085000}'),r={name:"public/templates/08_Data_Migration_Signoff_template.md"};function i(d,t,s,g,o,x){return n(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="데이터-이관-완료-및-정합성-검증-확인서-data-migration-sign-off" tabindex="-1">데이터 이관 완료 및 정합성 검증 확인서 (Data Migration Sign-off) <a class="header-anchor" href="#데이터-이관-완료-및-정합성-검증-확인서-data-migration-sign-off" aria-label="Permalink to “데이터 이관 완료 및 정합성 검증 확인서 (Data Migration Sign-off)”">​</a></h1><p>본 문서는 [발주회사명] (이하 &quot;발주처&quot;라 한다)과 주식회사 엠파시 (이하 &quot;수행사&quot;라 한다)가 추진 중인 [프로젝트명]과 관련하여, 기존 레거시 시스템에서 신규 구축 시스템으로의 데이터베이스 이관(Data Migration) 작업을 완료하고, 데이터 건수 및 정합성 무결성을 상호 검증한 결과를 확인하기 위해 작성하는 서식입니다.</p><hr><h3 id="_1-데이터-이관-개요" tabindex="-1">1. 데이터 이관 개요 <a class="header-anchor" href="#_1-데이터-이관-개요" aria-label="Permalink to “1. 데이터 이관 개요”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>사업명</strong></td><td style="text-align:left;">[계약서상 사업명]</td></tr><tr><td style="text-align:left;"><strong>이관 작업 일시</strong></td><td style="text-align:left;">202 년 월 일 [ ]:[ ] ~ 202 년 월 일 [ ]:[ ] (총 [ ] 시간 소요)</td></tr><tr><td style="text-align:left;"><strong>원천 시스템 (Source)</strong></td><td style="text-align:left;">[레거시 RDBMS 종류 / 버전 / DB명]</td></tr><tr><td style="text-align:left;"><strong>대상 시스템 (Target)</strong></td><td style="text-align:left;">PostgreSQL 17 (pgvector 활성화, 신규 운영 DB)</td></tr><tr><td style="text-align:left;"><strong>이관 도구 / 방식</strong></td><td style="text-align:left;">[자체 ETL 파이프라인 / Spring Batch / pg_dump 등]</td></tr><tr><td style="text-align:left;"><strong>작업 책임자 (수행사)</strong></td><td style="text-align:left;">직급: [ ] 성명: [ ] (DBA / Data Lead)</td></tr><tr><td style="text-align:left;"><strong>검증 책임자 (발주처)</strong></td><td style="text-align:left;">직급: [ ] 성명: [ ] (데이터 관리 담당자)</td></tr></tbody></table><hr><h3 id="_2-테이블별-데이터-건수-및-금액-정합성-대사표" tabindex="-1">2. 테이블별 데이터 건수 및 금액 정합성 대사표 <a class="header-anchor" href="#_2-테이블별-데이터-건수-및-금액-정합성-대사표" aria-label="Permalink to “2. 테이블별 데이터 건수 및 금액 정합성 대사표”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">테이블 구분</th><th style="text-align:left;">원천 테이블명 (Source)</th><th style="text-align:left;">신규 테이블명 (Target)</th><th style="text-align:center;">원천 건수 (A)</th><th style="text-align:center;">이관 건수 (B)</th><th style="text-align:center;">불일치 건수 (A-B)</th><th style="text-align:center;">정합률 (%)</th><th style="text-align:left;">금액/핵심값 대사 결과</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>사용자/회원</strong></td><td style="text-align:left;">TB_USER_MST</td><td style="text-align:left;">sys_user</td><td style="text-align:center;">124,530</td><td style="text-align:center;">124,530</td><td style="text-align:center;">0</td><td style="text-align:center;">100.0%</td><td style="text-align:left;">활성/휴면 상태 100% 일치</td></tr><tr><td style="text-align:left;"><strong>역할 및 권한</strong></td><td style="text-align:left;">TB_AUTH_GRP</td><td style="text-align:left;">sys_role_permission</td><td style="text-align:center;">3,420</td><td style="text-align:center;">3,420</td><td style="text-align:center;">0</td><td style="text-align:center;">100.0%</td><td style="text-align:left;">권한 매핑 무결성 통과</td></tr><tr><td style="text-align:left;"><strong>핵심 업무 마스터</strong></td><td style="text-align:left;">TB_PROD_INFO</td><td style="text-align:left;">domain_product</td><td style="text-align:center;">48,210</td><td style="text-align:center;">48,210</td><td style="text-align:center;">0</td><td style="text-align:center;">100.0%</td><td style="text-align:left;">상품 코드/카테고리 일치</td></tr><tr><td style="text-align:left;"><strong>거래/주문 이력</strong></td><td style="text-align:left;">TB_ORDER_HIST</td><td style="text-align:left;">domain_order</td><td style="text-align:center;">1,892,400</td><td style="text-align:center;">1,892,400</td><td style="text-align:center;">0</td><td style="text-align:center;">100.0%</td><td style="text-align:left;"><strong>총 누적 금액 100% 일치</strong><br>(오차: 0원)</td></tr><tr><td style="text-align:left;"><strong>첨부파일 메타</strong></td><td style="text-align:left;">TB_FILE_UPLOAD</td><td style="text-align:left;">oss_file_meta</td><td style="text-align:center;">87,600</td><td style="text-align:center;">87,600</td><td style="text-align:center;">0</td><td style="text-align:center;">100.0%</td><td style="text-align:left;">파일 크기 및 SHA256 대사 통과</td></tr><tr><td style="text-align:left;"><strong>합계</strong></td><td style="text-align:left;"><strong>총 [ ] 개 테이블</strong></td><td style="text-align:left;"><strong>총 [ ] 개 테이블</strong></td><td style="text-align:center;"><strong>[ ]</strong></td><td style="text-align:center;"><strong>[ ]</strong></td><td style="text-align:center;"><strong>0</strong></td><td style="text-align:center;"><strong>100.0%</strong></td><td style="text-align:left;"><strong>대사 성공</strong></td></tr></tbody></table><ul><li>불일치 데이터가 발생한 경우 그 예외 사유(예: 원천 데이터 중복 키 제거, 폐업 데이터 필터링 등)를 별첨 &quot;불일치 데이터 분석 보고서&quot;에 첨부하여 승인을 득함.</li></ul><hr><h3 id="_3-무결성-및-보안-검증-결과" tabindex="-1">3. 무결성 및 보안 검증 결과 <a class="header-anchor" href="#_3-무결성-및-보안-검증-결과" aria-label="Permalink to “3. 무결성 및 보안 검증 결과”">​</a></h3><ol><li><strong>개인정보 암호화 검증</strong>: <ul><li>주민등록번호, 계좌번호, 비밀번호 등 민감정보의 단방향(SHA-512) 및 양방향(AES-256) 암호화 적용 상태 전수 검사 완료.</li></ul></li><li><strong>외래키(FK) 참조 무결성 검증</strong>: <ul><li>고아 레코드(부모 없는 자식 데이터) 발생 건수: 0건.</li></ul></li><li><strong>AI 벡터 임베딩 생성 검증</strong>: <ul><li>RAG 지식 베이스 및 검색 대상 비정형 데이터 총 [ ] 건의 pgvector 임베딩 정상 생성 및 인덱스 빌드 완료.</li></ul></li></ol><hr><h3 id="_4-이관-후-데이터-롤백-및-보존-방안" tabindex="-1">4. 이관 후 데이터 롤백 및 보존 방안 <a class="header-anchor" href="#_4-이관-후-데이터-롤백-및-보존-방안" aria-label="Permalink to “4. 이관 후 데이터 롤백 및 보존 방안”">​</a></h3><ol><li>원천 레거시 시스템의 데이터는 만약의 사태를 대비하여 [ 30 ]일간 현행 상태로 보존하며, 쓰기 작업을 잠금(Read-Only) 처리합니다.</li><li>금일 이관된 신규 운영 데이터베이스의 전체 백업(Full Backup Dump)을 별도 오프라인 저장 매체에 이중 보관 조치하였습니다.</li></ol><hr><p>상기와 같이 데이터 이관 작업이 오차 없이 완벽하게 수행되었으며, 신규 시스템의 실데이터 운영 전환(Cut-over)에 동의함을 확인합니다.</p><p><strong>검증일자: 202 년 월 일</strong></p><p><strong>[발주처 데이터 검증 책임자]</strong></p><ul><li>소속 부서: [ ]</li><li>직급: [ ] 성명: [ ] (서명)</li></ul><p><strong>[수행사 데이터/DBA 총괄]</strong></p><ul><li>소속 부서: [주식회사 엠파시 기술본부]</li><li>직급: [ ] 성명: [ ] (서명)</li></ul>',22)])])}const _=e(r,[["render",i]]);export{f as __pageData,_ as default};
